function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
let z;
try { z = require("zod").z; } catch (e) { broken("cannot load zod: " + e.message); }
const mapSchema = z.map(z.string(), z.number()).default(new Map());
const m1 = mapSchema.parse(undefined);
if (!(m1 instanceof Map) || m1.size !== 0) broken("first parse did not return an empty Map");
m1.set("key", 42);
const m2 = mapSchema.parse(undefined);
if (!(m2 instanceof Map)) broken("second parse did not return a Map");
const setSchema = z.set(z.string()).default(new Set());
const s1 = setSchema.parse(undefined);
if (!(s1 instanceof Set) || s1.size !== 0) broken("first parse did not return an empty Set");
s1.add("item");
const s2 = setSchema.parse(undefined);
if (!(s2 instanceof Set)) broken("second parse did not return a Set");
if (m2.size !== 0 && s2.size !== 0) symptom("mutating a parse result of .default(new Map()) or .default(new Set()) changes later parses");
if (m2.size !== 0 || s2.size !== 0) broken("only one of the Map and Set defaults is shared");
console.log("OK: Map and Set defaults are copied on each parse");

